import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { Edit2, Trash2, Calendar, CheckCircle2, Circle, AlertCircle, TrendingUp, TrendingDown, Activity, Target, Check, X } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'bg-red-50 text-red-600 border-red-100',
      accent: 'bg-red-50/30 border-red-200 text-red-900',
      icon: <TrendingUp className="w-3.5 h-3.5" />
    };
    case '看跌': return {
      color: 'bg-green-50 text-green-600 border-green-100',
      accent: 'bg-green-50/30 border-green-200 text-green-900',
      icon: <TrendingDown className="w-3.5 h-3.5" />
    };
    case '震荡': return {
      color: 'bg-blue-50 text-blue-600 border-blue-100',
      accent: 'bg-blue-50/30 border-blue-200 text-blue-900',
      icon: <Activity className="w-3.5 h-3.5" />
    };
    default: return {
      color: 'bg-gray-50 text-gray-500 border-gray-100',
      accent: 'bg-gray-50/30 border-gray-200 text-gray-900',
      icon: <Circle className="w-3.5 h-3.5" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const completionStatus = insight.completionStatus;
  const { color, icon, accent } = getAssetStatusStyle(insight.status);

  const getCardStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-gray-50/50 border-emerald-100 opacity-90 grayscale-[0.2]';
      case '已失效': return 'bg-slate-50/80 border-slate-200 opacity-80 grayscale';
      default: return 'bg-white border-gray-200 shadow-[0_4px_20px_-4px_rgba(0,0,0,0.05)] hover:shadow-[0_20px_40px_-10px_rgba(0,0,0,0.08)] hover:-translate-y-1';
    }
  };

  const getTagStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-emerald-500 text-white shadow-emerald-100';
      case '已失效': return 'bg-slate-400 text-white shadow-slate-100';
      default: return 'bg-red-500 text-white shadow-red-100';
    }
  };

  const getStatusIcon = () => {
    switch (completionStatus) {
      case '已完成': return <CheckCircle2 className="w-3 h-3" />;
      case '已失效': return <AlertCircle className="w-3 h-3" />;
      default: return <Activity className="w-3 h-3 animate-pulse" />;
    }
  };

  return (
    <div className={`group relative mt-4 border rounded-[2.5rem] p-7 pt-9 transition-all duration-500 flex flex-col min-h-[420px] ${getCardStyle()}`}>

      {/* 状态标签 - 移除了外部剪裁并调整了定位 */}
      <div className="absolute -top-3.5 left-8 flex gap-2 z-20">
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`flex items-center gap-1.5 px-4 py-2 rounded-full text-[11px] font-black uppercase tracking-wider shadow-xl transition-all active:scale-95 hover:brightness-110 cursor-pointer ${getTagStyle()}`}
        >
          {getStatusIcon()}
          {completionStatus}
        </button>
      </div>

      {/* 背景巨型水印 */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.03] transition-opacity overflow-hidden rounded-[2.5rem]">
        {completionStatus === '已完成' && <Check className="w-64 h-64 text-emerald-600" />}
        {completionStatus === '已失效' && <X className="w-64 h-64 text-red-600" />}
        {completionStatus === '进行中' && <Activity className="w-64 h-64 text-gray-900" />}
      </div>

      <div className="relative z-10 flex justify-between items-center mb-6">
        <div>
          <h3 className="text-3xl font-black text-gray-900 tracking-tighter mb-1.5">{insight.symbol}</h3>
          <div className="flex items-center text-[11px] text-gray-400 gap-1.5 font-bold">
            <Calendar className="w-3.5 h-3.5 opacity-60" />
            {date}
          </div>
        </div>
        <div className={`px-4 py-2 rounded-2xl text-[12px] font-black border flex items-center gap-2 shadow-sm ${color}`}>
          {insight.status}
          {icon}
        </div>
      </div>

      <div className="relative z-10 space-y-5 flex-grow">
        <div className={`p-5 rounded-3xl border transition-colors ${completionStatus === '进行中' ? 'bg-gray-50/50 border-gray-100' : 'bg-white/40 border-transparent'}`}>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400 mb-2.5">核心观察</p>
          <p className="text-[14px] leading-relaxed font-medium text-gray-700">
            {insight.focusPoints}
          </p>
        </div>

        {insight.entryLevel && (
          <div className="flex items-center justify-between p-4 px-5 rounded-2xl border border-dashed bg-gray-50 border-gray-200">
            <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">入场参考</p>
            <div className="flex items-center gap-2">
              <Target className="w-3.5 h-3.5 text-red-400" />
              <p className="text-lg font-black tracking-tighter text-gray-900">{insight.entryLevel}</p>
            </div>
          </div>
        )}

        <div className={`p-6 rounded-3xl border-l-[8px] transition-all ${completionStatus === '进行中' ? accent : 'bg-gray-100 border-gray-300 text-gray-500'}`}>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60 mb-2.5">执行策略</p>
          <p className={`text-[15px] font-bold leading-relaxed ${completionStatus === '进行中' ? 'text-gray-900' : 'text-gray-400'}`}>
            {insight.strategy}
          </p>
        </div>
      </div>

      <div className="relative z-10 mt-6 pt-6 border-t border-gray-100/60 flex justify-end items-center gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300">
        <button 
          onClick={() => onEdit(insight)}
          className="px-4 py-2 text-gray-400 hover:text-gray-900 hover:bg-gray-50 rounded-xl transition-all flex items-center gap-2 text-[12px] font-black"
        >
          <Edit2 className="w-4 h-4" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="px-4 py-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all flex items-center gap-2 text-[12px] font-black"
        >
          <Trash2 className="w-4 h-4" />
          删除
        </button>
      </div>
    </div>
  );
};

export default MarketCard;

import React from 'react';
import { MarketInsight } from '../types';
import { Sparkles, PieChart } from 'lucide-react';

