  const total = insights.length;

  return (
    <div className="mb-14 space-y-6">
      {/* 精简后的 AI 操作栏 */}
      <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-[0_10px_30px_-10px_rgba(0,0,0,0.05)] flex flex-col md:flex-row gap-6 items-center justify-between">
        <div className="flex items-center gap-5">
          <div className="w-14 h-14 bg-red-50 rounded-2xl flex items-center justify-center">
            <PieChart className="w-6 h-6 text-red-500" />
          </div>
          <div>
            <h4 className="text-sm font-black text-gray-900">市场综述分析</h4>
            <p className="text-[11px] text-gray-400 font-bold uppercase tracking-wider">当前共有 {total} 条活跃洞察</p>
          </div>
