        <button 
          onClick={onGenerateAI}
          disabled={isGeneratingAI || total === 0}
          className="w-full md:w-auto flex items-center justify-center gap-3 px-10 py-4 bg-gray-900 text-white rounded-2xl font-black text-sm hover:bg-black transition-all shadow-2xl shadow-gray-200 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed group"
        >
          <Sparkles className={`w-4 h-4 text-amber-400 ${isGeneratingAI ? 'animate-spin' : 'group-hover:animate-bounce'}`} />
